public static int findNthLeapYear(int Y, int N) {
    int year = Y + 1;
    int count = 0;
    while (count < N) {
        if (isLeapYear(year)) {
            count++;
        }
        if (count == N) {
            return year;
        }
        year++;
    }
    return year;
}

