public boolean canArrange(int[] arr, int k) {
    int n = arr.length;
    // If the length is odd, it's impossible to form n/2 pairs
    if (n % 2 != 0) {
        return false;
    }

    // Count the frequency of each remainder when divided by k
    int[] remainderCount = new int[k];
    for (int num : arr) {
        int remainder = ((num % k) + k) % k; // Handle negative numbers
        remainderCount[remainder]++;
    }

    // For remainder 0, the count must be even
    if (remainderCount[0] % 2 != 0) {
        return false;
    }

    // For each remainder i from 1 to k/2, the count of i must equal the count of (k - i)
    for (int i = 1; i <= k / 2; i++) {
        if (remainderCount[i] != remainderCount[k - i]) {
            return false;
        }
    }

    return true;
}

