public int minOperations(int n) {
    // The array is arr[i] = 2*i + 1 for i in [0, n-1]
    // Target value is the average, which for this arithmetic sequence is: (first + last) / 2 = (1 + (2n-1)) / 2 = n
    // So target = n
    // The number of operations is the sum of |arr[i] - target| for all i where arr[i] < target,
    // because each operation moves 1 unit from a larger to a smaller element.
    // Actually, total operations = sum_{i=0}^{n-1} max(0, target - arr[i])

    // For n=3: target=3, arr=[1,3,5], deficits: 3-1=2, 3-3=0, 3-5<0 -> total=2. Correct.
    // For n=6: target=6, arr=[1,3,5,7,9,11], deficits: 6-1=5, 6-3=3, 6-5=1, 6-7<0, ... -> total=5+3+1=9. Correct.

    int target = n;
    int operations = 0;
    // Only consider elements below or equal to target (actual deficits)
    for (int i = 0; i < n; i++) {
        int val = 2 * i + 1;
        if (val < target) {
            operations += target - val;
        }
    }
    return operations;
}

