public static int findSmallestInteger(int n) {
    String s = Integer.toString(n);
    char[] arr = s.toCharArray();
    int len = arr.length;

    // Find the rightmost digit that is smaller than the digit to its right
    int i = len - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) {
        i--;
    }

    if (i < 0) {
        return -1; // No greater permutation exists
    }

    // Find the smallest digit to the right of position i that is greater than arr[i]
    int j = len - 1;
    while (arr[j] <= arr[i]) {
        j--;
    }

    // Swap arr[i] and arr[j]
    char temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;

    // Sort the suffix (elements after i) in ascending order
    // Since the suffix is in descending order, we just reverse it
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = arr[left];
        arr[left] = arr[right];
        arr[right] = t;
        left++;
        right--;
    }

    String result = new String(arr);
    try {
        return Integer.parseInt(result);
    } catch (NumberFormatException e) {
        return -1;
    }
}

